mapper.select:
SELECT *
FROM room_stage_record
WHERE room_id = #{roomId}
  AND stage_id = #{stageId}
LIMIT 1

mapper.update:
UPDATE room_stage_record
SET stage_id      = #{stageId},
    unlock_time   = #{unlockTime},
    unlock_reason = #{unlockReason},
    is_open       = #{isOpen}
WHERE id = #{id}
